#!/bin/bash
#SBATCH --nodes=2
#SBATCH --gpus-per-node=4

#!/bin/sh
#SBATCH --job-name decode           # this is a parameter to help you sort your job when listing it
#SBATCH --error decode_logs_%j.error     # optional. By default a file slurm-{jobid}.out will be created
#SBATCH --output decode_logs_%j.out      # optional. By default the error and output files are merged
#SBATCH --mem 20GB
#SBATCH --time 00:50:00                  # maximum run time
#SBATCH --partition shared-gpu
#SBATCH --gres=gpu:1

input_file=${1}
output_file=${2}
model_name=${3}
checkpoint_path=${4}
src_lang=${5}
tgt_lang=${6}
num_beams=${7}

srun python ./scripts/python/encoder2decoder/decode/decode.py ${input_file} ${output_file} ${model_name} ${checkpoint_path} ${src_lang} ${tgt_lang} ${num_beams}
